package com.github.cleytonorocha.hub.service.google;

import com.github.cleytonorocha.hub.dto.google.GoogleTaskDtos.*;
import com.github.cleytonorocha.hub.integration.google.GoogleTasksApiClient;
import com.github.cleytonorocha.hub.security.AuthContext;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestClientResponseException;

import java.sql.Date;
import java.sql.Timestamp;
import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.ZoneId;
import java.util.*;
import java.util.concurrent.*;

@Service
public final class GoogleTasksService {
	private final JdbcTemplate jdbc;
	private final GoogleOAuthService oauth;
	private final GoogleTasksApiClient google;
	private final ExecutorService syncExecutor = Executors.newCachedThreadPool(r -> { Thread t=new Thread(r,"google-tasks-sync"); t.setDaemon(true); return t; });
	private final ConcurrentHashMap<String,CompletableFuture<SyncResult>> syncs = new ConcurrentHashMap<>();
	private final ConcurrentHashMap<String,Object> ownerLocks = new ConcurrentHashMap<>();
	public GoogleTasksService(JdbcTemplate jdbc,GoogleOAuthService oauth,GoogleTasksApiClient google){this.jdbc=jdbc;this.oauth=oauth;this.google=google;}

	public SyncResult synchronize(){String owner=AuthContext.userId(); CompletableFuture<SyncResult> future=syncs.compute(owner,(k,old)->old!=null&&!old.isDone()?old:CompletableFuture.supplyAsync(()->performSync(owner),syncExecutor)); future.whenComplete((v,e)->syncs.remove(owner,future)); try{return future.join();}catch(CompletionException e){if(e.getCause() instanceof RuntimeException r)throw r;throw e;}}
	public List<TaskList> listTaskLists(){String o=AuthContext.userId(),token=oauth.accessToken(o);return google.listAllTaskLists(token).stream().map(l->new TaskList(l.id(),l.title(),isSelected(o,l.id()))).toList();}
	public List<Task> listTasks(String listId){String o=AuthContext.userId(),token=oauth.accessToken(o);TaskList l=findList(token,listId);if(!isSelected(o,l.id()))return List.of();return google.listAllTasks(token,l.id(),l.title()).stream().filter(t->!t.deleted()).toList();}
	public Task createTask(String listId,String title,LocalDate dueDate){String o=AuthContext.userId();synchronized(ownerLocks.computeIfAbsent(o,k->new Object())){if(title==null||title.isBlank())throw new IllegalArgumentException("Task title is required.");String token=oauth.accessToken(o);TaskList l=findList(token,listId);if(!isSelected(o,l.id()))throw new IllegalArgumentException("Select the Google Tasks list before creating tasks.");Instant started=Instant.now();try{Task t=google.createTask(token,listId,title.trim(),dueDate,l.title());persistTask(o,t,null);reconcileReminder(o,t);return t;}catch(RestClientException e){List<Task> matches;try{matches=google.listAllTasks(oauth.accessToken(o),listId,l.title()).stream().filter(t->!t.deleted()&&title.trim().equals(t.title())&&Objects.equals(dueDate,t.dueDate())&&updatedAfter(t.updated(),started)).toList();}catch(RuntimeException unavailable){throw new GoogleSyncException("The save could not be confirmed. Refresh Google Tasks before retrying.");}if(matches.size()==1){persistTask(o,matches.getFirst(),null);reconcileReminder(o,matches.getFirst());return matches.getFirst();}throw new GoogleSyncException("The save could not be confirmed. Refresh Google Tasks before retrying.");}}}
	public Task updateTask(String listId,String taskId,TaskChange change){String o=AuthContext.userId();synchronized(ownerLocks.computeIfAbsent(o,k->new Object())){if(change==null||change.completed()==null||change.expectedUpdated()==null||change.expectedUpdated().isBlank())throw new IllegalArgumentException("Task version and completion state are required.");String token=oauth.accessToken(o);TaskList l=findList(token,listId);if(!isSelected(o,l.id()))throw new IllegalArgumentException("The Google Tasks list is paused.");Task current;try{current=google.getTask(token,listId,taskId,l.title());}catch(RestClientResponseException e){if(e.getStatusCode().value()==404)throw new TaskConflictException(null);throw e;}if(current==null||current.deleted())throw new TaskConflictException(null);if(!change.expectedUpdated().equals(current.updated())||(change.expectedEtag()!=null&&!change.expectedEtag().equals(current.etag())))throw new TaskConflictException(current);Task updated;try{updated=google.updateTask(token,listId,taskId,change.dueDate(),change.completed(),current.etag(),l.title());}catch(RestClientResponseException e){if(e.getStatusCode().value()!=412)throw e;try{throw new TaskConflictException(google.getTask(token,listId,taskId,l.title()));}catch(RestClientResponseException gone){if(gone.getStatusCode().value()==404)throw new TaskConflictException(null);throw gone;}}persistTask(o,updated,null);reconcileReminder(o,updated);return updated;}}
	public void setListSelected(String listId,boolean selected){String o=AuthContext.userId();synchronized(ownerLocks.computeIfAbsent(o,k->new Object())){String c=oauth.connectionId(o),token=oauth.accessToken(o);TaskList l=findList(token,listId);int n=jdbc.update("UPDATE google_task_list_state SET selected=?,deleted=FALSE WHERE owner_id=? AND connection_id=? AND task_list_id=?",selected,o,c,l.id());if(n==0)jdbc.update("INSERT INTO google_task_list_state(owner_id,connection_id,task_list_id,selected,deleted) VALUES(?,?,?,?,FALSE)",o,c,l.id(),selected);if(!selected)jdbc.update("UPDATE hub_task_notification SET state='CANCELLED' WHERE owner_id=? AND connection_id=? AND task_list_id=? AND state='PENDING'",o,c,l.id());}}
	public List<Notification> notifications(boolean unreadOnly){String o=AuthContext.userId(),c=oauth.connectionId(o);String q="SELECT notification_id,task_list_id,task_id,due_date,scheduled_at,state,overdue,created_at,read_at FROM hub_task_notification WHERE owner_id=? AND connection_id=? AND state<>'CANCELLED'"+(unreadOnly?" AND state='UNREAD'":"")+" ORDER BY scheduled_at DESC";return jdbc.query(q,(r,n)->new Notification(r.getString("notification_id"),r.getString("task_list_id"),r.getString("task_id"),r.getDate("due_date").toLocalDate(),r.getTimestamp("scheduled_at").toInstant(),r.getString("state"),r.getBoolean("overdue"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("read_at")==null?null:r.getTimestamp("read_at").toInstant()),o,c);}
	public void markNotificationRead(String id){String o=AuthContext.userId(),c=oauth.connectionId(o);int n=jdbc.update("UPDATE hub_task_notification SET state='READ',read_at=? WHERE owner_id=? AND connection_id=? AND notification_id=? AND state='UNREAD'",Timestamp.from(Instant.now()),o,c,id);if(n==0)throw new IllegalArgumentException("Notification was not found or was already read.");}
	public void markAllNotificationsRead(){String o=AuthContext.userId(),c=oauth.connectionId(o);jdbc.update("UPDATE hub_task_notification SET state='READ',read_at=? WHERE owner_id=? AND connection_id=? AND state='UNREAD'",Timestamp.from(Instant.now()),o,c);}
	public ReminderSettings reminderSettings(){String o=AuthContext.userId();LocalTime t=jdbc.queryForObject("SELECT reminder_time FROM hub_task_user_settings WHERE owner_id=?",(r,n)->r.getTime(1).toLocalTime(),o);return new ReminderSettings(t.toString());}
	public ReminderSettings saveReminderSettings(String value){String o=AuthContext.userId();LocalTime time;try{time=LocalTime.parse(value);}catch(RuntimeException e){throw new IllegalArgumentException("Enter a valid reminder time.");}jdbc.update("UPDATE hub_task_user_settings SET reminder_time=? WHERE owner_id=?",java.sql.Time.valueOf(time),o);String c=oauth.connectionId(o);List<ReminderRow> pending=jdbc.query("SELECT notification_id,due_date FROM hub_task_notification WHERE owner_id=? AND connection_id=? AND state='PENDING'",(r,n)->new ReminderRow(r.getString(1),r.getDate(2).toLocalDate()),o,c);LocalDate today=LocalDate.now();for(ReminderRow row:pending){Instant scheduled=row.dueDate().minusDays(1).atTime(time).atZone(ZoneId.systemDefault()).toInstant();if(!row.dueDate().isAfter(today))noticeUpdate(o,c,row.id(),"state='CANCELLED'",null);else if(!scheduled.isAfter(Instant.now()))noticeUpdate(o,c,row.id(),"scheduled_at=?,state='UNREAD',overdue=TRUE",Timestamp.from(scheduled));else noticeUpdate(o,c,row.id(),"scheduled_at=?",Timestamp.from(scheduled));}return reminderSettings();}

	@Scheduled(fixedDelay=60000) public void deliverDueNotifications(){Instant now=Instant.now();List<OwnerSettings> owners=jdbc.query("SELECT owner_id,reminder_time FROM hub_task_user_settings",(r,n)->new OwnerSettings(r.getString(1),r.getTime(2).toLocalTime()));for(OwnerSettings os:owners){synchronized(ownerLocks.computeIfAbsent(os.owner(),k->new Object())){LocalDate today=LocalDate.now();String selectedList="EXISTS(SELECT 1 FROM google_task_list_state l WHERE l.owner_id=hub_task_notification.owner_id AND l.connection_id=hub_task_notification.connection_id AND l.task_list_id=hub_task_notification.task_list_id AND l.selected=TRUE AND l.deleted=FALSE)";jdbc.update("UPDATE hub_task_notification SET state='UNREAD',overdue=FALSE WHERE owner_id=? AND state='PENDING' AND scheduled_at<=? AND due_date>? AND "+selectedList,os.owner(),Timestamp.from(now),Date.valueOf(today));jdbc.update("UPDATE hub_task_notification SET state='CANCELLED' WHERE owner_id=? AND state='PENDING' AND due_date<=? AND "+selectedList,os.owner(),Date.valueOf(today));}}}
	public void disconnect(){String o=AuthContext.userId();synchronized(ownerLocks.computeIfAbsent(o,k->new Object())){CompletableFuture<SyncResult> f=syncs.remove(o);if(f!=null)f.cancel(true);oauth.disconnect(o);}}

	private SyncResult performSync(String o){synchronized(ownerLocks.computeIfAbsent(o,k->new Object())){String c=oauth.connectionId(o),token=oauth.accessToken(o);List<TaskList> remote=google.listAllTaskLists(token);String run=UUID.randomUUID().toString();Set<String> seen=new HashSet<>();List<TaskList> lists=new ArrayList<>();List<Task> tasks=new ArrayList<>();for(TaskList rl:remote){String id=rl.id();seen.add(id);boolean selected=isSelected(o,id);persistList(o,c,id,selected,run);lists.add(new TaskList(id,rl.title(),selected));if(!selected)continue;for(Task t:google.listAllTasks(token,id,rl.title())){persistTask(o,t,run);reconcileReminder(o,t);if(!t.deleted())tasks.add(t);}jdbc.update("UPDATE google_task_state SET deleted=TRUE WHERE owner_id=? AND connection_id=? AND task_list_id=? AND last_sync_run IS DISTINCT FROM ?",o,c,id,run);cancelDeleted(o,c,id);}if(seen.isEmpty()){jdbc.update("UPDATE google_task_list_state SET deleted=TRUE WHERE owner_id=? AND connection_id=?",o,c);jdbc.update("UPDATE google_task_state SET deleted=TRUE WHERE owner_id=? AND connection_id=?",o,c);jdbc.update("UPDATE hub_task_notification SET state='CANCELLED' WHERE owner_id=? AND connection_id=? AND state IN('PENDING','UNREAD')",o,c);}else{String p=String.join(",",Collections.nCopies(seen.size(),"?"));List<Object>a=new ArrayList<>(List.of(o,c));a.addAll(seen);jdbc.update("UPDATE google_task_list_state SET deleted=TRUE WHERE owner_id=? AND connection_id=? AND task_list_id NOT IN("+p+")",a.toArray());jdbc.update("UPDATE google_task_state SET deleted=TRUE WHERE owner_id=? AND connection_id=? AND task_list_id NOT IN("+p+")",a.toArray());jdbc.update("UPDATE hub_task_notification SET state='CANCELLED' WHERE owner_id=? AND connection_id=? AND task_list_id NOT IN("+p+") AND state IN('PENDING','UNREAD')",a.toArray());}oauth.markSynchronized(o);return new SyncResult("CONNECTED",Instant.now(),lists,tasks);}}
	private TaskList findList(String token,String id){return google.listAllTaskLists(token).stream().filter(l->l.id().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Google task list was not found."));}
	private void persistList(String o,String c,String id,boolean selected,String run){int n=jdbc.update("UPDATE google_task_list_state SET deleted=FALSE,selected=?,last_sync_run=? WHERE owner_id=? AND connection_id=? AND task_list_id=?",selected,run,o,c,id);if(n==0)jdbc.update("INSERT INTO google_task_list_state(owner_id,connection_id,task_list_id,selected,deleted,last_sync_run) VALUES(?,?,?,?,FALSE,?)",o,c,id,selected,run);}
	private void persistTask(String o,Task t,String run){String c=oauth.connectionId(o);Date due=t.dueDate()==null?null:Date.valueOf(t.dueDate());int n=jdbc.update("UPDATE google_task_state SET remote_updated=?,remote_etag=?,due_date=?,completed=?,deleted=?,last_sync_run=? WHERE owner_id=? AND connection_id=? AND task_list_id=? AND task_id=?",t.updated(),t.etag(),due,t.completed(),t.deleted(),run,o,c,t.listId(),t.id());if(n==0){ensureList(o,c,t.listId());jdbc.update("INSERT INTO google_task_state(owner_id,connection_id,task_list_id,task_id,remote_updated,remote_etag,due_date,completed,deleted,last_sync_run) VALUES(?,?,?,?,?,?,?,?,?,?)",o,c,t.listId(),t.id(),t.updated(),t.etag(),due,t.completed(),t.deleted(),run);}}
	private void ensureList(String o,String c,String list){int n=jdbc.update("UPDATE google_task_list_state SET deleted=FALSE WHERE owner_id=? AND connection_id=? AND task_list_id=?",o,c,list);if(n==0)jdbc.update("INSERT INTO google_task_list_state(owner_id,connection_id,task_list_id,selected,deleted) VALUES(?,?,?,TRUE,FALSE)",o,c,list);}
	private void reconcileReminder(String o,Task t){String c=oauth.connectionId(o);if(!isSelected(o,t.listId())){jdbc.update("UPDATE hub_task_notification SET state='CANCELLED' WHERE owner_id=? AND connection_id=? AND task_list_id=? AND task_id=? AND state='PENDING'",o,c,t.listId(),t.id());return;}LocalDate today=LocalDate.now();if(t.deleted()||t.completed()||t.dueDate()==null||!t.dueDate().isAfter(today)){jdbc.update("UPDATE hub_task_notification SET state='CANCELLED' WHERE owner_id=? AND connection_id=? AND task_list_id=? AND task_id=? AND state='PENDING'",o,c,t.listId(),t.id());return;}LocalTime time=jdbc.queryForObject("SELECT reminder_time FROM hub_task_user_settings WHERE owner_id=?",(r,n)->r.getTime(1).toLocalTime(),o);Instant scheduled=t.dueDate().minusDays(1).atTime(time).atZone(ZoneId.systemDefault()).toInstant();boolean overdue=!scheduled.isAfter(Instant.now());List<String> stale=jdbc.query("SELECT notification_id FROM hub_task_notification WHERE owner_id=? AND connection_id=? AND task_list_id=? AND task_id=? AND due_date<>? AND state IN('PENDING','UNREAD')",(r,n)->r.getString(1),o,c,t.listId(),t.id(),Date.valueOf(t.dueDate()));for(String id:stale)jdbc.update("UPDATE hub_task_notification SET state='CANCELLED' WHERE owner_id=? AND notification_id=?",o,id);List<Notice> existing=jdbc.query("SELECT notification_id,state FROM hub_task_notification WHERE owner_id=? AND connection_id=? AND task_list_id=? AND task_id=? AND due_date=?",(r,n)->new Notice(r.getString(1),r.getString(2)),o,c,t.listId(),t.id(),Date.valueOf(t.dueDate()));if(!existing.isEmpty()){Notice x=existing.getFirst();if(x.state().equals("CANCELLED"))jdbc.update("UPDATE hub_task_notification SET scheduled_at=?,state=?,overdue=?,read_at=NULL,created_at=? WHERE owner_id=? AND notification_id=?",Timestamp.from(scheduled),overdue?"UNREAD":"PENDING",overdue,Timestamp.from(Instant.now()),o,x.id());else if(x.state().equals("PENDING")&&overdue)jdbc.update("UPDATE hub_task_notification SET scheduled_at=?,state='UNREAD',overdue=TRUE WHERE owner_id=? AND notification_id=?",Timestamp.from(scheduled),o,x.id());else if(x.state().equals("PENDING"))jdbc.update("UPDATE hub_task_notification SET scheduled_at=? WHERE owner_id=? AND notification_id=?",Timestamp.from(scheduled),o,x.id());return;}String state=overdue?"UNREAD":"PENDING";try{jdbc.update("INSERT INTO hub_task_notification(owner_id,notification_id,connection_id,task_list_id,task_id,due_date,scheduled_at,state,overdue,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",o,UUID.randomUUID().toString(),c,t.listId(),t.id(),Date.valueOf(t.dueDate()),Timestamp.from(scheduled),state,overdue,Timestamp.from(Instant.now()));}catch(DuplicateKeyException ignored){}}
	private void cancelDeleted(String o,String c,String list){jdbc.update("UPDATE hub_task_notification SET state='CANCELLED' WHERE owner_id=? AND connection_id=? AND task_list_id=? AND task_id IN(SELECT task_id FROM google_task_state WHERE owner_id=? AND connection_id=? AND task_list_id=? AND deleted=TRUE) AND state IN('PENDING','UNREAD')",o,c,list,o,c,list);}
	private boolean isSelected(String o,String list){String c=oauth.connectionId(o);List<Boolean> v=jdbc.query("SELECT selected FROM google_task_list_state WHERE owner_id=? AND connection_id=? AND task_list_id=? AND deleted=FALSE",(r,n)->r.getBoolean(1),o,c,list);return v.isEmpty()||v.getFirst();}
	private void noticeUpdate(String o,String c,String id,String fields,Object value){String q="UPDATE hub_task_notification SET "+fields+" WHERE owner_id=? AND connection_id=? AND notification_id=?";if(fields.contains("?"))jdbc.update(q,value,o,c,id);else jdbc.update(q,o,c,id);}
	private boolean updatedAfter(String s,Instant when){try{return s!=null&&Instant.parse(s).isAfter(when.minusSeconds(5));}catch(RuntimeException e){return false;}}
	private record ReminderRow(String id,LocalDate dueDate){} private record OwnerSettings(String owner,LocalTime time){} private record Notice(String id,String state){}
	public static class TaskConflictException extends RuntimeException{private final Task currentTask;public TaskConflictException(Task t){super("Task changed in Google Tasks.");currentTask=t;}public Task currentTask(){return currentTask;}}
	public static class GoogleSyncException extends RuntimeException{public GoogleSyncException(String m){super(m);}}
}
